table=dict(zip(codons,aas))
stops={'TAA','TAG','TGA'}
def translate(s):
    return ''.join(table.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def find_orf_in(s):
    n=len(s); res=[]
    for f in range(3):
        i=f
        while i+3<=n:
            if s[i:i+3]=='ATG':
                j=i
                while j+3<=n and s[j:j+3] not in stops:
                    j+=3
                res.append((i,j,j-i))
                i=j
            else:
                i+=3
    return res

