def rc(s): return ''.join(comp[b] for b in reversed(s))

def ir_search(s, minarm=8, maxloop=200):
    n=len(s); best=[]
    for i in range(n-2*minarm):
        for k in range(minarm, 60):
            if i+2*k>n: break
            arm=s[i:i+k]; r=rc(arm)
            # search r in downstream window
            j=s.find(r, i+k, min(n, i+k+maxloop+k))
            if j!=-1:
                best.append((k, i+1, j+k, j-i-k, arm))
    best.sort(reverse=True)
    return best
