with open('region.fasta') as f:
    lines=f.read().splitlines()
seq=''.join(l.strip() for l in lines if not l.startswith('>'))
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
def rc(s): return ''.join(comp[b] for b in reversed(s))
stops={'TAA','TAG','TGA'}
def longest_stopfree(s):
    n=len(s); best=(0,None)
    for f in range(3):
        start=f
        i=f
        while i+3<=n:
            if s[i:i+3] in stops:
                L=i-start
                if L>best[0]: best=(L,(start+1,i))
                start=i+3
            i+=3
        L=((n-f)//3*3+f)-start
        # recompute properly
        if n-start>=0:
            L=n-start
            # truncate to codon boundary
            L=(L//3)*3
            if L>best[0]: best=(L,(start+1,start+L))
    return best
print("+ strand longest stop-free:", longest_stopfree(seq))
print("- strand longest stop-free:", longest_stopfree(rc(seq)))
